def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """

    # Split the string by spaces and filter out any empty strings resulting from multiple spaces
    letters = [char for char in test.split() if char]

    # Dictionary to store counts of each letter
    count_dict = {}

    # Count occurrences of each letter
    for char in letters:
        count_dict[char] = count_dict.get(char, 0) + 1

    # Find the maximum frequency among all letters
    if not count_dict:
        return {}

    max_count = max(count_dict.values())

    # Collect all letters that have this maximum frequency
    result = {letter: count for letter, count in count_dict.items() 
              if count == max_count}

    return result

# --- Testing the function with provided examples ---
print(histogram('a b c'))          # {'a': 1, 'b': 1, 'c': 1}
print(histogram('a b b a'))        # {'a': 2, 'b': 2}
print(histogram('a b c a b'))      # {'a': 2, 'b': 2}
print(histogram('b b b b a'))      # {'b': 4}
print(histogram(''))               # {}

# Additional test for tie-breaking logic
print(histogram('x x y z z w'))    # Should return all with count 1: {'x': 1, 'y': 1, 'z': 1, 'w': 1}

